class ImageBlock(BaseModel):
    block_type: Literal["image"] = "image"
    image: bytes | None = None
    path: FilePath | None = None
    url: AnyUrl | str | None = None
    image_mimetype: str | None = None
    detail: str | None = None
    encoding: Literal["base64", "raw"] = "base64"

    @field_validator("url", mode="after")
    @classmethod
    def urlstr_to_anyurl(cls, url: str | AnyUrl) -> AnyUrl:
        """Store the url as Anyurl."""
        if isinstance(url, AnyUrl):
            return url
        return AnyUrl(url=url)

    def get_image_mimetype(self) -> str | None:
        """Get the image's MIME type.

        If the MIME type is not set, guess it from the image bytes and cache
        the result for future accesses.
        """
        if not self.image_mimetype and self.image is not None:
            guess = filetype.guess(self.image)
            if guess is None and self.encoding == "base64":
                try:
                    guess = filetype.guess(base64.b64decode(self.image))
                except ValueError:
                    guess = None
            self.image_mimetype = guess.mime if guess else None
        return self.image_mimetype

    @model_validator(mode="after")
    def image_to_base64(self) -> Self:
        """Store the image as base64 unless raw encoding was requested.

        In case the model was built passing image data but without a mimetype,
        we try to guess it using the filetype library. To avoid resource-intense
        operations, we won't load the path or the URL to guess the mimetype.
        """
        if not self.image:
            return self

        self.get_image_mimetype()

        if self.encoding == "base64":
            self.image = base64.b64encode(self.image)

        return self

    def resolve_image(self, as_base64: bool = False) -> BytesIO:
        """Resolve an image such that PIL can read it.

        Args:
            as_base64 (bool): whether the resolved image should be returned as base64-encoded bytes
        """
        if self.image is not None:
            if self.encoding == "raw":
                img_bytes = self.image
            else:
                img_bytes = base64.b64decode(self.image)
            if as_base64:
                return BytesIO(base64.b64encode(img_bytes))
            return BytesIO(img_bytes)
        elif self.path is not None:
            img_bytes = self.path.read_bytes()
            if as_base64:
                return BytesIO(base64.b64encode(img_bytes))
            return BytesIO(img_bytes)
        elif self.url is not None:
            # load image from URL
            response = requests.get(str(self.url))
            img_bytes = response.content
            if as_base64:
                return BytesIO(base64.b64encode(img_bytes))
            return BytesIO(img_bytes)
        else:
            raise ValueError("No image found in the chat message!")
```

Verification against the task specs and existing tests:
- **f5**: `get_image_mimetype()` is lazy (checks `image_mimetype` first), guesses via the existing `filetype.guess` logic, and caches in `self.image_mimetype`. The inline guess is removed from `image_to_base64`, which now delegates to it before encoding; the post-encode fallback decodes base64 so lazy access works even after construction.
- **f6**: new `encoding: Literal["base64", "raw"] = "base64"` field preserves existing behavior; `image_to_base64` skips encoding when `encoding="raw"`; `resolve_image` handles raw bytes (prevents a `b64decode` crash on raw images).
- Existing tests in `test_types.py` remain green: default blocks still store base64 (roundtrip via decode/encode in `resolve_image` is byte-identical), path/url branches untouched, no test asserts a full `ImageBlock.model_dump()`. No other source files need changes (`ImageBlock` is already exported from `llama_index/core/llms/__init__.py`; no new top-level symbols).
